package com.example.starter.ili;

/**
 * 缺陷读数所属检测回合：OLD 为上一回合，NEW 为本回合。
 */
public enum RunSide {
    OLD,
    NEW
}

package com.example.starter.ili;

/**
 * 缺陷分级：STABLE=稳定（增长率 &lt; 5%/年），GROWING=增长（&gt;= 5%/年），SEVERE=严重（&gt;= 15%/年）。
 */
public enum Grade {
    STABLE,
    GROWING,
    SEVERE
}

package com.example.starter.ili;

/**
 * 批次状态：ALIGNED=已对齐待复核，SEALED=已封板（终态，拒绝一切修改）。
 */
public enum BatchStatus {
    ALIGNED,
    SEALED
}

package com.example.starter.ili;

/**
 * 复核状态：PENDING=待复核，CONFIRMED=已确认，DOWNGRADED=已降级。
 */
public enum ReviewStatus {
    PENDING,
    CONFIRMED,
    DOWNGRADED
}

package com.example.starter.ili;

/**
 * 复核动作：CONFIRM=确认维持原分级，DOWNGRADE=将分级下调一级。
 */
public enum ReviewDecision {
    CONFIRM,
    DOWNGRADE
}

package com.example.starter.ili;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * ILI 服务的基础设施配置；提供可替换的时钟，便于时间相关测试使用可控时钟。
 */
@Configuration
public class IliConfiguration {

    /**
     * 业务时钟，默认使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

