package com.example.starter.ili.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 单条缺陷读数输入（合成数据）。
 *
 * @param defectRef    检测方缺陷编号，同批次同回合内唯一
 * @param absPositionM 缺陷绝对里程，单位米
 * @param depthPct     缺陷深度，占壁厚百分比，取值 0~100
 */
public record DefectInput(
        @NotBlank @Size(max = 64) String defectRef,
        @NotNull @DecimalMin("0.0") @DecimalMax("500000.0") Double absPositionM,
        @NotNull @DecimalMin("0.0") @DecimalMax("100.0") Double depthPct) {
}

package com.example.starter.ili.dto;

import java.time.LocalDate;
import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 对齐批次提交请求：一次双回合缺陷清单导入，按 requestId 幂等。
 *
 * @param requestId   客户端幂等请求标识
 * @param segmentId   管段标识
 * @param runOldId    上一检测回合标识
 * @param runNewId    本检测回合标识
 * @param runOldDate  上一回合检测日期
 * @param runNewDate  本回合检测日期，必须晚于上一回合
 * @param oldDefects  上一回合缺陷清单
 * @param newDefects  本回合缺陷清单
 */
public record SubmitBatchRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String segmentId,
        @NotBlank @Size(max = 64) String runOldId,
        @NotBlank @Size(max = 64) String runNewId,
        @NotNull LocalDate runOldDate,
        @NotNull LocalDate runNewDate,
        @NotEmpty List<@Valid DefectInput> oldDefects,
        @NotEmpty List<@Valid DefectInput> newDefects) {
}

package com.example.starter.ili.dto;

import java.math.BigDecimal;

/**
 * 缺陷读数视图，用于“新发现”“已消失”清单。
 *
 * @param defectRef    检测方缺陷编号
 * @param absPositionM 缺陷绝对里程，单位米
 * @param depthPct     缺陷深度，占壁厚百分比
 */
public record ReadingView(
        String defectRef,
        BigDecimal absPositionM,
        BigDecimal depthPct) {
}

package com.example.starter.ili.dto;

import com.example.starter.ili.ReviewDecision;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 复核结论提交请求：对增长、严重缺陷逐条确认或降级。
 *
 * @param pairId   匹配对主键
 * @param decision 复核动作：CONFIRM=确认，DOWNGRADE=降级
 * @param reviewer 复核人标识
 * @param comment  复核备注，可为空
 */
public record ReviewRequest(
        @NotNull Long pairId,
        @NotNull ReviewDecision decision,
        @NotBlank @Size(max = 64) String reviewer,
        @Size(max = 512) String comment) {
}

package com.example.starter.ili.dto;

import java.time.Instant;

/**
 * 封板结果视图；封板为终态，重复封板返回相同的首次封板时间。
 *
 * @param batchId  批次主键
 * @param status   批次状态，恒为 SEALED
 * @param sealedAt 首次封板时间（UTC）
 */
public record SealResponse(
        long batchId,
        String status,
        Instant sealedAt) {
}

